"""Generate Obhod-owned data; Flowseal strategies are generated by fetch_vendor."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from obhod.core.strategy import Block


def main():
    epic = ["--filter-tcp=443", "--hostlist=${LISTS}/list-epic.txt",
            "--hostlist=${LISTS}/list-epic-user.txt", "--hostlist-exclude=${LISTS}/list-exclude-user.txt",
            "--ipset-exclude=${LISTS}/ipset-exclude-user.txt"]
    game = ["--ipset=${LISTS}/ipset-game.txt", "--ipset-exclude=${LISTS}/ipset-exclude.txt",
            "--ipset-exclude=${LISTS}/ipset-exclude-user.txt"]
    variants = {
        "E0": ("epic-tcp", "Без desync · контроль", []),
        "E1": ("epic-tcp", "Multisplit · 568", ["--dpi-desync=multisplit", "--dpi-desync-split-pos=1",
                 "--dpi-desync-split-seqovl=568", "--dpi-desync-split-seqovl-pattern=${BIN}/tls_clienthello_4pda_to.bin"]),
        "E2": ("epic-tcp", "Fake TLS · AutoTTL", ["--dpi-desync=fake,multisplit", "--dpi-desync-split-pos=1,midsld",
                 "--dpi-desync-fake-tls=${BIN}/tls_clienthello_www_google_com.bin",
                 "--dpi-desync-fake-tls-mod=rnd,dupsid,sni=www.google.com", "--dpi-desync-autottl=2"]),
        "E3": ("epic-tcp", "Fake + fakedsplit · TS", ["--dpi-desync=fake,fakedsplit", "--dpi-desync-fooling=ts"]),
        "E4": ("epic-tcp", "Hostfakesplit", ["--dpi-desync=hostfakesplit", "--dpi-desync-hostfakesplit-mod=host=www.google.com"]),
        "U0": ("game-udp", "Без desync · контроль", []),
        "U1": ("game-udp", "Fake · 12 повторов", ["--dpi-desync=fake", "--dpi-desync-repeats=12",
                 "--dpi-desync-fake-unknown-udp=${BIN}/ACTIVE_GAME_UDP.bin", "--dpi-desync-cutoff=n2"]),
        "U2": ("game-udp", "Fake · AutoTTL", ["--dpi-desync=fake", "--dpi-desync-repeats=6",
                 "--dpi-desync-autottl=2", "--dpi-desync-cutoff=n3"]),
        "U3": ("game-udp", "Fake · STUN / zero", ["--dpi-desync=fake", "--dpi-desync-repeats=6",
                 "--dpi-desync-fake-unknown-udp=${BIN}/stun.bin",
                 "--dpi-desync-fake-unknown-udp=${BIN}/zero.bin", "--dpi-desync-cutoff=n3"]),
        "U4": ("game-udp", "IP fragmentation", ["--dpi-desync=ipfrag2", "--dpi-desync-ipfrag-pos-udp=8", "--dpi-desync-cutoff=n3"]),
        "U5": ("game-udp", "Fake + UDP length", ["--dpi-desync=fake,udplen", "--dpi-desync-udplen-increment=2", "--dpi-desync-cutoff=n3"]),
        "T1": ("game-tcp", "Multisplit · any protocol", ["--dpi-desync=multisplit", "--dpi-desync-split-pos=1",
                 "--dpi-desync-split-seqovl=568", "--dpi-desync-split-seqovl-pattern=${BIN}/tls_clienthello_4pda_to.bin",
                 "--dpi-desync-cutoff=n3"]),
        "T2": ("game-tcp", "Fake + multisplit", ["--dpi-desync=fake,multisplit", "--dpi-desync-split-pos=1", "--dpi-desync-cutoff=n3"]),
    }
    blocks = []
    for identifier, (category, label, flags) in variants.items():
        prefix = epic if category == "epic-tcp" else [f"--filter-{category[5:]}=${{GAME_{category[5:].upper()}}}", *game]
        args = prefix + flags
        if category.startswith("game-") and flags:
            args.append("--dpi-desync-any-protocol=1")
        blocks.append(Block(identifier, category, tuple(args), identifier, label).to_dict())
    dest = ROOT / "strategies" / "custom" / "fortnite.json"
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(json.dumps({"schema": 1, "blocks": blocks}, ensure_ascii=False, indent=2), encoding="utf-8")
    hosts = "epicgames.com\nepicgames.dev\nol.epicgames.com\nfortnite.com\neasyanticheat.net\neasy.ac\n"
    (ROOT / "lists" / "list-epic.txt").write_text(hosts, encoding="utf-8")
    for name in ("list-epic-user.txt", "list-general-user.txt", "list-exclude-user.txt", "ipset-exclude-user.txt", "ipset-fortnite.txt"):
        (ROOT / "lists" / name).touch(exist_ok=True)
    backup = ROOT / "lists" / "ipset-all.txt.backup"
    loaded = ROOT / "lists" / "ipset-all.txt"
    if backup.exists() and loaded.read_text().strip() == "203.0.113.113/32":
        loaded.write_bytes(backup.read_bytes())
    targets = [
        ("yt-web", "youtube", "google-tcp", "www.youtube.com", "/", "https"),
        ("yt-short", "youtube", "google-tcp", "youtu.be", "/", "https"),
        ("yt-image", "youtube", "google-tcp", "i.ytimg.com", "/", "https"),
        ("yt-video", "youtube", "google-tcp", "redirector.googlevideo.com", "/", "https"),
        ("google", "youtube", "google-tcp", "www.google.com", "/", "https"),
        ("gstatic", "youtube", "google-tcp", "www.gstatic.com", "/", "https"),
        ("discord", "discord", "general-tcp", "discord.com", "/", "https"),
        ("discord-ws", "discord", "general-tcp", "gateway.discord.gg", "/?v=10&encoding=json", "websocket"),
        ("discord-cdn", "discord", "general-tcp", "cdn.discordapp.com", "/", "https"),
        ("discord-updates", "discord", "general-tcp", "updates.discord.com", "/", "https"),
        ("epic-account", "fortnite", "epic-tcp", "account-public-service-prod.ol.epicgames.com", "/account/api/version", "https"),
        ("epic-lightswitch", "fortnite", "epic-tcp", "lightswitch-public-service-prod.ol.epicgames.com", "/lightswitch/api/service/bulk/status", "https"),
        ("epic-fortnite", "fortnite", "epic-tcp", "fortnite-public-service-prod11.ol.epicgames.com", "/fortnite/api/version", "https"),
        ("epic-cdn", "fortnite", "epic-tcp", "download.epicgames.com", "/", "https"),
        ("epic-eos", "fortnite", "epic-tcp", "api.epicgames.dev", "/", "https"),
        ("epic-eac", "fortnite", "epic-tcp", "www.easy.ac", "/", "https"),
    ]
    records = [dict(zip(("id", "service", "category", "host", "path", "kind"), x)) for x in targets]
    (ROOT / "data").mkdir(exist_ok=True)
    (ROOT / "data" / "targets.json").write_text(json.dumps(
        {"schema": 1, "note": "HTTP 401/403/404 proves transport only. Matchmaking WS/XMPP/QoS must be captured locally; no guessed endpoints.",
         "targets": records}, ensure_ascii=False, indent=2), encoding="utf-8")


if __name__ == "__main__":
    main()

